_restart_tasks: set[asyncio.Task] = set()

# Compatibility field in restart outcomes: worker-turn grace is deliberately zero.
_DRAIN_DEADLINE_S = 0.0
RESTART_DURABLE_STATE_BUDGET_S = 30.0
RESTART_OUTCOME_RECORD_BUDGET_S = 5.0
# Durable flush and outcome journal are bounded; worker turns add no wait at all.
RESTART_PREPARATION_BUDGET_S = 50.0
# restart_guard reap <= 6 с; resume <= 2 с, а его INTERRUPTED fallback stop <= 5 с.
RESTART_ABORT_CLEANUP_BUDGET_S = 15.0
RESTART_PREPARATION_CEILING_S = (
    RESTART_PREPARATION_BUDGET_S + RESTART_ABORT_CLEANUP_BUDGET_S
)


def _drain_sessions() -> list:
    """Живые сессии одним местом — тест подменяет именно её."""
    return list(manager.sessions.values())


def _record_restart_outcome(outcome: dict) -> None:
    """Записать итог дренажа ДО сигнала: после него отчитываться уже некому.

    Процесс умирает внутри workflow, поэтому ни HTTP-ответ, ни живой TG-канал итог
    не донесут — переживает рестарт только запись на диск. Потребитель — существующий
    журнал сессии в дашборде; нового эндпоинта и таблицы не заводим (#220 T3).
    """
    from app.db import add_log

    ts = datetime.now(timezone.utc)
    summary = (
        f"[system] рестарт: дренаж {outcome['waited_s']:.1f} с, "
        f"разорвано ходов: {outcome['cut_turns']}"
    )
    logger.warning(summary)
    for session_id in outcome["cut_ids"]:
        add_log(session_id, ts, "system",
                f"{summary}. Твой ход прерван; сессия восстановится после запуска, "
                "автоматического повтора самого хода нет.")


async def _record_restart_outcome_bounded(outcome: dict) -> dict | None:
    """Keep a locked audit write from stretching the front-end preparation ceiling."""
    try:
        await asyncio.wait_for(
            asyncio.to_thread(_record_restart_outcome, outcome),
            timeout=RESTART_OUTCOME_RECORD_BUDGET_S,
        )
        return None
    except Exception as error:
        logger.warning("could not record restart outcome: %s: %s",
                       type(error).__name__, error)
        return {
            "ok": False,
            "phase": "restart_outcome",
            "task_class": "_record_restart_outcome",
            "reason": f"{type(error).__name__}: {error}",
        }


async def _drain_restart_durable_state() -> dict:
    """Bound the final session DB/log flush before the restart becomes irreversible."""
    try:
        result = await asyncio.wait_for(
            manager.drain_restart_persistence(),
            timeout=RESTART_DURABLE_STATE_BUDGET_S,
        )
        if isinstance(result, dict) and result.get("ok") is False:
            losses = result.get("losses") or []
            reasons = [str(loss.get("reason", "")) for loss in losses if loss.get("reason")]
            return {
                **result,
                "phase": "session_db",
                "task_class": "AgentSession._drain_handoff_log_writes",
                "reason": "; ".join(reasons) or "session journal persistence failed",
            }
        return result
    except TimeoutError:
        return {
            "ok": False,
            "phase": "session_db",
            "task_class": "AgentSession._drain_handoff_log_writes",
            "reason": (
                "TimeoutError: deadline exceeded after "
                f"{RESTART_DURABLE_STATE_BUDGET_S}s"
            ),
        }
    except Exception as error:
        return {
            "ok": False,
            "phase": "session_db",
            "task_class": "AgentSession._drain_handoff_log_writes",
            "reason": f"{type(error).__name__}: {error}",
        }


def _arm_supervisor_exit_guard(
    *,
    target_pid: int | None = None,
    start_ticks: int | None = None,
    post_cleanup_budget: float = restart_guard.RESTART_POST_CLEANUP_EXIT_BUDGET_S,
    event_log: str | Path | None = None,
) -> restart_guard.GuardHandle:
    """Arm the independent helper after all pre-signal durability barriers pass."""
    from app.backend_jsonrpc import process_start_time

    target_pid = os.getpid() if target_pid is None else target_pid
    start_ticks = process_start_time(target_pid) if start_ticks is None else start_ticks
    return restart_guard.arm_guard(
        target_pid=target_pid,
        start_ticks=start_ticks,
        post_cleanup_budget=post_cleanup_budget,
        event_log=event_log,
    )


async def restart_preflight() -> dict:
    """Close both admission gates BEFORE systemd is invoked (#230 T6).

    A gate inside the lifespan is too late: by then `systemctl restart` is already committed
    and nobody can be told "no". Order matters — close admission FIRST, so nothing new starts
    a side effect while we wait, THEN drain what was already accepted.

    Живая мутация рестарт больше НЕ отменяет (решение юзера 28.08.2026). Отсюда возвращался
    `ok: False`, и `restart_server` отвечал 409 «still in flight after 0s» — то самое «нажатие
    не делало ничего», ради отмены которого бюджет дренажа и обнулили. Дренаж оставлен
    вызовом, но ждёт он ровно `app.main.MUTATING_DRAIN_BUDGET_S`, а тот 0.0 — сегодня здесь
    не ждут ничего, и ненулевой бюджет вернул бы сюда ожидание, которого никто не просил.
    Незавершённые мутации считает `_do_restart_service` для отчёта.
    """
    from app import main as app_main

    # BOTH gates, both before the first await. Closing only the HTTP half left a window where
    # a new agent turn could start after the drain had taken its snapshot — so the very turn
    # the drain protects was the one the signal cut (#237 T3).
    manager.begin_drain()
    app_main.close_mutating_admission()
    await app_main.drain_mutating_requests()
    return {"ok": True}


# HTTP uses Starlette BackgroundTasks, so the response lifecycle itself is the flush barrier.
_RESPONSE_FLUSH_PAUSE_S = 0.0
_WATCHDOG_MARGIN_S = 120.0  # durable flush + outcome write, generously


def _watchdog_budget_s() -> float:
    """How long the safety net waits before deciding the restart is not coming.

    `MUTATING_DRAIN_BUDGET_S` is read at call time on purpose: `app.main` imports this module,
    so a module-level import would be circular, and copying the number would give one budget
    two owners — the same mistake in a new place.
    """
    from app import main as app_main

    return (_RESPONSE_FLUSH_PAUSE_S          # let the HTTP response leave first
            + app_main.MUTATING_DRAIN_BUDGET_S  # the restart path drains HTTP a second time
            + _WATCHDOG_MARGIN_S)            # durable flush + the outcome write

#: Which restart attempt is current. A watchdog belongs to the attempt that armed it: firing
#: into a LATER attempt would strip descriptors out of systemd's store and reopen both gates
#: mid-transaction, from a coroutine that has no idea any of it is happening.
_restart_attempt = 0
# Последняя ОТМЕНА рестарта: причина и время. Отдаётся следующим ответом /api/restart,
# иначе «ok, scheduled» неотличимо от рестарта, который потом молча не состоялся.
_last_restart_abort: dict | None = None


async def _reopen_admission_if_still_alive(attempt: int = 0) -> None:
    """Undo the preflight's admission gate if the restart never arrived (#230 T6).

    A real restart kills this process, so in the happy path this coroutine simply dies with it
    and the sleep is never observed. Reaching the end means the signal did not do its job.

    It outlasts the remaining bounded preparation and stands down if its own attempt is no
    longer current. Worker turns are not part of this budget because restart never waits for
    them.
    """
    budget = _watchdog_budget_s()
    await asyncio.sleep(budget)
    if attempt != _restart_attempt:
        logger.info("restart watchdog for attempt %d stood down: attempt %d is current",
                    attempt, _restart_attempt)
        return
    # Reopening the gates is not enough. A fleet that was already prepared is quiesced and
    # stored: those agents would stay deaf and their descriptors would sit in systemd's store
    # until it fills up. Give them their readers back too (found by the pre-mortem).
    await _abort_restart(
        f"no restart within {budget}s of a successful preflight")
    logger.error(
        "restart did not happen within %ss after a successful preflight; "
        "both admissions reopened", budget,
    )


async def _prepare_restart_service() -> dict:
    """Finish every fallible restart step while the HTTP caller can still see its result."""
    try:
        return await asyncio.wait_for(
            _do_restart_service(), timeout=RESTART_PREPARATION_BUDGET_S,
        )
    except TimeoutError:
        reason = (
            "restart preparation deadline exceeded after "
            f"{RESTART_PREPARATION_BUDGET_S:g}s"
        )
        cleanup_timed_out = False
        try:
            await asyncio.wait_for(
                _abort_restart(reason), timeout=RESTART_ABORT_CLEANUP_BUDGET_S,
            )
        except TimeoutError:
            cleanup_timed_out = True
            from app import main as app_main
            manager.end_drain()
            app_main.open_mutating_admission()
            logger.critical(
                "restart abort cleanup exceeded %.0fs; admissions reopened after guard's "
                "bounded disarm window",
                RESTART_ABORT_CLEANUP_BUDGET_S,
            )
        if cleanup_timed_out:
            reason += (
                "; abort cleanup deadline exceeded after "
                f"{RESTART_ABORT_CLEANUP_BUDGET_S:g}s"
            )
        return {
            "ok": False,
            "phase": "preparation",
            "reason": reason,
            "waited_s": (
                RESTART_PREPARATION_CEILING_S
                if cleanup_timed_out else RESTART_PREPARATION_BUDGET_S
            ),
            "preparation_ceiling_s": RESTART_PREPARATION_CEILING_S,
            "cut_turns": 0,
            "cut_names": [],
            "cut_ids": [],
        }
    except BaseException:
        from app import main as app_main
        # A failed preparation must not leave admission closed indefinitely.
        await _abort_restart("the restart path failed")
        app_main.open_mutating_admission()
        logger.exception("restart path failed; admission reopened")
        raise


async def _signal_restart_after_response() -> dict:
    """Signal only after the prepared outcome had time to leave over HTTP."""
    await asyncio.sleep(_RESPONSE_FLUSH_PAUSE_S)
    try:
        from app.live_broker import broker
        broker.close_subscribers()
        os.kill(os.getpid(), signal.SIGINT)
        return {"ok": True}
    except BaseException as error:
        reason = f"{type(error).__name__}: {error}"
        await _abort_restart(f"restart signal failed: {reason}")
        logger.exception("restart signal failed; admission reopened")
        raise


async def _signal_restart_and_disarm_on_failure(watchdog: asyncio.Task) -> dict:
    try:
        return await _signal_restart_after_response()
    except BaseException:
        watchdog.cancel()
        raise


async def _restart_service_after_response(*, signal: bool = True) -> dict:
    """Compatibility seam for TG/tests: prepare, then optionally signal this supervisor."""
    outcome = await _prepare_restart_service()
    if signal and outcome.get("ok") and outcome.get("prepared"):
        await _signal_restart_after_response()
    return outcome


async def _abort_restart(reason: str) -> None:
    """Reopen admission after disarming this restart attempt."""
    from app import main as app_main

    # Publish before cleanup: read-only heartbeat remains available even when rollback must
    # stay fail-closed, so the dashboard still names the current attempt's failure.
    app_main.note_restart_failure(reason)
    # One owner for every abort, including the watchdog's normal-return path. Leaving a helper
    # armed while resuming the old generation lets a later teardown marker kill a recovered
    # supervisor from an attempt that no longer owns it.
    try:
        await restart_guard.abort_guard(reason)
    except BaseException as error:
        logger.critical(
            "restart guard disarm unproven; refusing rollback/gate reopen: %s: %s",
            type(error).__name__,
            error,
        )
        raise
    manager.end_drain()
    app_main.open_mutating_admission()
    # Отмена уходила ТОЛЬКО в лог: вызвавший получил ok/scheduled и ждал события, которого
    # не будет. 25.08 так сгорело пять рестартов подряд и полчаса на «рестарт был?».
    global _last_restart_abort
    _last_restart_abort = {"reason": str(reason), "at": datetime.now(timezone.utc).isoformat()}
    logger.warning("restart aborted (%s): no signal sent", reason)


async def _do_restart_service() -> dict:
    from app import main as app_main

    # Нажатая кнопка рестарта ничем не отменяется (решение юзера 28.08.2026). Раньше живой
    # мутирующий вызов отменял рестарт целиком, и нажатие не делало ничего — это ровно то,
    # чего быть не должно. Незавершённые мутации по-прежнему пересчитываются, но только для
    # ОТЧЁТА: агент увидит неизвестный исход и переспросит, а рестарт состоится.
    await app_main.drain_mutating_requests()
    abandoned_mutations = app_main.inflight_mutating_count()

    started = time.monotonic()
    sessions = _drain_sessions()
    cut_sessions = [session for session in sessions if session.is_busy]
    # Restart never hands a loaded backend over. shutdown_all() will call the ordinary
    # session.stop() path for every session; a RUNNING one persists INTERRUPTED and startup's
    # auto_resume_all() wakes it again.
    # Работа, начавшаяся во время подготовки, рестарт больше НЕ отменяет: гонка «успел ли
    # кто-то влезть» решалась в пользу того, кто влез, и кнопка проигрывала её тем чаще, чем
    # больше в контуре агентов.
    abandoned_mutations = max(abandoned_mutations, app_main.inflight_mutating_count())

    cut_ids = [session.id for session in cut_sessions]
    outcome = {
        "ok": True,
        "prepared": True,
        "handed_over": [],
        "waited_s": time.monotonic() - started,
        "turn_grace_s": _DRAIN_DEADLINE_S,
        "cut_turns": len(cut_sessions),
        "cut_names": [session.name for session in cut_sessions],
        "cut_ids": cut_ids,
        "restore_after_restart": cut_ids,
        "abandoned_mutations": abandoned_mutations,
    }
    durable_state = await _drain_restart_durable_state()
    if isinstance(durable_state, dict) and durable_state.get("ok") is False:
        logger.error(
            "restart durable-state barrier failed: pid=%d phase=%s task_class=%s reason=%s",
            os.getpid(),
            durable_state["phase"],
            durable_state["task_class"],
            durable_state["reason"],
        )
        outcome["journal_loss"] = durable_state
    elif isinstance(durable_state, dict) and durable_state.get("retried_log_writes"):
        outcome["retried_log_writes"] = durable_state["retried_log_writes"]
    record_loss = await _record_restart_outcome_bounded(outcome)
    if record_loss is not None:
        # Побочный учёт не имеет права отменить основное действие: дедлайн назван
        # безусловным, и сбой записи не делает рестарт менее обязательным (класс #215).
        outcome.setdefault("journal_loss", record_loss)
    _arm_supervisor_exit_guard()
    return outcome


def _disarm_watchdog_if_aborted(done: asyncio.Task, watchdog: asyncio.Task) -> None:
    """Stand the watchdog down when the attempt ended WITHOUT signalling (#237).

    Deliberately not "whenever the attempt finishes": the one case the watchdog exists for is
    a signal that failed to kill us, and there the attempt has completed normally. An abort,
    by contrast, has already reopened both gates itself, so a live watchdog there can only
    fire into whatever comes next.
    """
    if done.cancelled():
        watchdog.cancel()
        return
    if done.exception() is not None:
        watchdog.cancel()  # the failure path reopened the gates already
        return
    outcome = done.result()
    if isinstance(outcome, dict) and outcome.get("ok") is False:
        watchdog.cancel()


async def restart_server(background_tasks: BackgroundTasks | None = None):
    watchdog = None
    preflight_succeeded = False
    try:
        from app import main as app_main
        app_main.clear_restart_failure()
        verdict = await restart_preflight()
        # В проде ветка недостижима: preflight отказов больше не возвращает. Держит её мок в
        # tests/test_fd_adopt.py — снимать вместе с ним и контрактом `ok` (follow-up).
        if not verdict["ok"]:
            raise HTTPException(409, verdict["reason"])
        preflight_succeeded = True
        # The preflight left BOTH gates closed so nothing new starts. If the restart does not
        # actually happen, they must not stay shut: a stuck-closed gate answers every mutating
        # tool call with "retry later" and refuses every agent turn, forever.
        global _restart_attempt
        _restart_attempt += 1
        attempt = _restart_attempt
        watchdog = asyncio.create_task(_reopen_admission_if_still_alive(attempt))
        _restart_tasks.add(watchdog)
        watchdog.add_done_callback(_restart_tasks.discard)
        # Await every fallible preparation step so THIS response names THIS attempt's
        # failure/journal loss. Only the self-signal stays deferred, giving JSON time to flush.
        outcome = await _restart_service_after_response(signal=False)
        if not outcome.get("ok"):
            watchdog.cancel()
            raise HTTPException(409, detail=outcome)
        if outcome.get("prepared"):
            if background_tasks is not None:
                # Starlette runs BackgroundTasks only after the response body is sent. This is
                # the ordering guarantee the old fixed 0.5-second guess could not provide.
                background_tasks.add_task(
                    _signal_restart_and_disarm_on_failure, watchdog,
                )
            else:
                # In-process caller (TG) and unit tests have no ASGI response lifecycle.
                task = asyncio.create_task(
                    _signal_restart_and_disarm_on_failure(watchdog)
                )
                _restart_tasks.add(task)
                task.add_done_callback(_restart_tasks.discard)
                task.add_done_callback(
                    lambda done: _disarm_watchdog_if_aborted(done, watchdog)
                )
    except BaseException:
        # Nothing was scheduled, so nobody downstream will ever reopen the gates for us.
        if watchdog is not None:
            watchdog.cancel()
        # Once preflight succeeded, downstream owns rollback. If guard disarm was unproven,
        # reopening here would let new work start under a helper that may still kill us.
        if not preflight_succeeded:
            app_main.open_mutating_admission()
            manager.end_drain()
        raise
    global _last_restart_abort
    previous_abort, _last_restart_abort = _last_restart_abort, None
    response = {**outcome, "ok": True, "scheduled": bool(outcome.get("prepared"))}
    if previous_abort:
        response["previous_attempt_aborted"] = previous_abort
    return response


@router.post("/api/restart")
async def restart_server_route(background_tasks: BackgroundTasks):
    return await restart_server(background_tasks)


# ── GitHub Webhook (CI failure routing) ──

_FAILURE_CONCLUSIONS = {"failure", "timed_out", "startup_failure"}


def _parse_repo_to_scope() -> dict[str, str]:
    raw = os.environ.get("GITHUB_REPO_SCOPE_MAP", "")
    if not raw:
        return {}
    result = {}
    for item in raw.split(","):
        item = item.strip()
        if "=" in item:
            repo, scope = item.split("=", 1)
            result[repo.strip()] = scope.strip()
    return result


REPO_TO_SCOPE = _parse_repo_to_scope()


def _verify_github_signature(payload: bytes, signature: str, secret: str) -> bool:
    # compare_digest prevents timing attacks on the signature check
    expected = "sha256=" + hmac.new(secret.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)


async def _fetch_failed_log(owner: str, repo: str, run_id: int, token: str) -> str:
    import httpx
    headers = {"Authorization": f"token {token}", "Accept": "application/vnd.github+json"}
    async with httpx.AsyncClient(timeout=15) as client:
        resp = await client.get(
            f"https://api.github.com/repos/{owner}/{repo}/actions/runs/{run_id}/jobs",
            headers=headers,
        )
        if resp.status_code != 200:
            return f"(failed to fetch jobs: HTTP {resp.status_code})"
        jobs = resp.json().get("jobs", [])
        failed_job = next((j for j in jobs if j.get("conclusion") in _FAILURE_CONCLUSIONS), None)
        if not failed_job:
            return "(no failed job found)"
        job_id = failed_job["id"]
        log_resp = await client.get(
            f"https://api.github.com/repos/{owner}/{repo}/actions/jobs/{job_id}/logs",
            headers=headers,
            follow_redirects=True,
        )
        if log_resp.status_code != 200:
            return f"(failed to fetch log: HTTP {log_resp.status_code})"
        lines = log_resp.text.splitlines()
        return "\n".join(lines[-50:])


@router.post("/api/webhook/github")
async def github_webhook(request: Request):
    secret = [secret len=35 tail=ET"], "")
    if not secret:
        return JSONResponse({"error": "webhook not configured"}, status_code=500)

    body = await request.body()
    signature = request.headers.get("X-Hub-Signature-256", "")
    if not signature or not _verify_github_signature(body, signature, secret):
        return JSONResponse({"error": "invalid signature"}, status_code=403)

    event = request.headers.get("X-GitHub-Event", "")
    if event != "workflow_run":
        return {"ok": True, "skipped": event}

    try:
        payload = json.loads(body)
    except json.JSONDecodeError:
        return JSONResponse({"error": "invalid JSON"}, status_code=400)

    action = payload.get("action")
    workflow_run = payload.get("workflow_run") or {}
    conclusion = workflow_run.get("conclusion")

    if action != "completed" or conclusion not in _FAILURE_CONCLUSIONS:
        return {"ok": True, "skipped": f"{action}/{conclusion}"}

    repository = payload.get("repository") or {}
    repo_full = repository.get("full_name", "")
    scope = REPO_TO_SCOPE.get(repo_full)
    if not scope:
        logger.warning(f"No scope mapping for repo: {repo_full}")
        return {"ok": True, "skipped": f"unmapped repo {repo_full}"}

    workflow_name = workflow_run.get("name", "unknown")
    run_id = workflow_run.get("id")
    run_url = workflow_run.get("html_url", "")
    head_commit = workflow_run.get("head_commit") or {}
    commit_sha = str(head_commit.get("id", ""))[:7]
    commit_msg = str(head_commit.get("message", "")).split("\n")[0]

    token = [secret len=26 tail=EN"], "")
    error_log = ""
    if token and run_id:
        owner, repo = repo_full.split("/", 1)
        try:
            error_log = await _fetch_failed_log(owner, repo, run_id, token)
        except Exception as e:
            error_log = f"(log fetch error: {e})"

    message = (
        f"🔴 CI FAIL: {repo_full}\n"
        f"Workflow: {workflow_name}, Run #{run_id}\n"
        f"Commit: {commit_sha} \"{commit_msg}\"\n"
    )
    if error_log:
        message += f"Error:\n{error_log}\n"
    message += f"URL: {run_url}"

    orch_name = manager._find_orchestrator_name(scope)
    if not orch_name:
        logger.warning(f"No orchestrator for scope: {scope}")
        return JSONResponse({"error": f"no orchestrator for scope {scope}"}, status_code=404)

    session = await manager.ensure_loaded(orch_name, scope)
    if not session:
        return JSONResponse({"error": f"orchestrator {orch_name} not loadable"}, status_code=404)

    try:
        from app.events import MessageProvenance

        provenance = MessageProvenance(
            origin="system", senders=("ci",),
            subtype="ci_failure", ref=str(run_id or ""),
        )
        await manager.send(
            session.id, message, provenance=provenance,
        )
        logger.info(f"CI failure routed to {orch_name}: {repo_full} run #{run_id}")
        return {"ok": True, "routed_to": orch_name}
    except Exception as e:
        logger.error(f"Failed to send CI failure to {orch_name}: {e}")
        return JSONResponse({"error": str(e)}, status_code=500)

"""Единственное правило допуска воркеров по квоте пула (#343).

Для пула считаются две величины в процентах:

* **норма** — доля окна, прошедшая по времени: 0% в начале окна, 100% в момент сброса;
* **допуск** — линейно ``TOLERANCE_START_PP`` п.п. в начале окна → ``TOLERANCE_END_PP``
  п.п. в момент сброса.

Гейтящиеся полосы (Sol и Claude-воркеры) блокируются, когда расход ушёл выше суммы
нормы и допуска; поверх этого на всех воркеров действуют жёсткие ``HARD_STOP_PCT``.
Luna и Spark диагональ не проходят вовсе — они дешёвые, их единственный стоп жёсткий.
Оркестраторы гейт не проходят никогда: это свойство ВЫЗЫВАЮЩЕГО, и здесь его нет —
`is_orchestrator` проверяется в `app/session.py` и `app/manager.py` до вызова гейта.

Правило смотрит ТОЛЬКО на текущую точку и истории не помнит: обнуление счётчика оно
переживает само, потому что после сброса и расход, и доля окна начинаются заново.

Неизвестная квота ПРОПУСКАЕТ. Это сквозное решение, а не послабление одного вызова:
отказ на `unknown` при спавне создавал сессию, которую следующий обязательный `/send`
отбивал 429 — мёртвую (#227).
"""

